options.helpers:
// The static route table of the Providers page.
//
// One row per route of the owner's static selection, in the collector's row
// order. The names and the icons of a provider are the ones the capacity
// cards above the table read; the left cell is the share of the binding
// window that is left, with the pace beside it.
const ROUTE_PROVIDERS = [
  { account: 'claude', name: 'Claude', icon: '\u2733', background: '#d97757', foreground: '#fff' },
  { account: 'codex', name: 'Codex', icon: '\u229b', background: '#e8e8e8', foreground: '#111' },
  { account: 'ollama', name: 'Ollama', icon: '\u25c9', background: '#f2f2f2', foreground: '#111' },
  { account: 'opencode-go', name: 'OpenCode Go', icon: '{}', background: '#2b2f3a', foreground: '#7dd3fc' },
  { account: 'antigravity', name: 'Antigravity', icon: 'A', background: 'linear-gradient(135deg,#4f8cff,#c86bfa)', foreground: '#fff' },
  { account: 'grok', name: 'Grok', icon: '\u2298', background: '#000', foreground: '#fff' },
  { account: 'openrouter', name: 'OpenRouter', icon: '\u21c4', background: '#6466f1', foreground: '#fff' },
];

// The name a provider is read by, when the approved list does not name it.
const ROUTE_NAMES = {
  'cloudflare-workers-ai': 'Cloudflare',
  'cohere': 'Cohere',
  'google': 'Google',
  'groq': 'Groq',
  'inception': 'Inception',
  'kilo': 'Kilo',
  'kilo-keyed': 'Kilo (keyed)',
  'mistral': 'Mistral',
  'nvidia': 'NVIDIA',
  'opencode': 'OpenCode Zen',
  'orcarouter': 'Orcarouter',
  'ovh': 'OVH',
  'pi': 'Pi',
  'poolside': 'Poolside',
  'requesty': 'Requesty',
  'upstage': 'Upstage',
  'vercel': 'Vercel',
  'zai': 'Zai',
};

// The number a row holds, or nothing when the row holds no number.
function routeNumber(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return isFinite(number) ? number : null;
}

// The name, the icon and the colours a provider is read by.
function routeIdentity(provider) {
  const approved = ROUTE_PROVIDERS.find((entry) => entry.account === provider);
  if (approved) {
    return {
      name: approved.name,
      icon: approved.icon,
      background: approved.background,
      foreground: approved.foreground,
    };
  }
  const name = ROUTE_NAMES[provider] || String(provider || '').split(/[-_\s]+/).filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  return { name: name, icon: name.charAt(0).toUpperCase(), background: '#2b2f3a', foreground: '#fff' };
}

// The routes of the page and the routing state, read out of the rows.
function routeRead(rows) {
  const routes = new Map();
  let routing = null;
  for (const row of rows || []) {
    const value = routeNumber(row.value);
    if (row.field === 'routing') {
      if (value !== null) { routing = value; }
      continue;
    }
    const key = String(row.row === null || row.row === undefined ? '' : row.row);
    if (!key) { continue; }
    let entry = routes.get(key);
    if (!entry) {
      entry = {
        row: key,
        role: '',
        provider: '',
        model: '',
        displayName: '',
        usedFor: '',
        left: null,
        pace: null,
        reset: null,
      };
      routes.set(key, entry);
    }
    if (row.field === 'info') {
      entry.role = row.role || '';
      entry.provider = row.provider || '';
      entry.model = row.model || '';
      entry.displayName = row.display_name || row.model || '';
      entry.usedFor = row.used_for || '';
    } else if (row.field === 'left') { entry.left = value; }
    else if (row.field === 'pace') { entry.pace = value; }
    else if (row.field === 'reset') { entry.reset = value; }
  }
  return { routes: Array.from(routes.values()), routing: routing };
}

// How long a route has left before its window resets.
function routeRelative(reset, now) {
  if (reset === null) { return ''; }
  const seconds = reset - now;
  if (seconds <= 0) { return '0m'; }
  const hours = seconds / 3600;
  if (hours < 1) { return Math.round(seconds / 60) + 'm'; }
  if (hours < 48) { return Math.floor(hours) + 'h ' + Math.round((hours % 1) * 60) + 'm'; }
  return (hours / 24).toFixed(1) + 'd';
}

// The pace of a route: how far it is from the share it expects to be left.
function routePace(left, pace, reset, now) {
  if (left === null) { return { text: 'no reading', cls: '' }; }
  if (left <= 0) {
    const relative = routeRelative(reset, now);
    return {
      text: '\u2715 spent' + (relative ? ' \u00b7 resets in ' + relative : ''),
      cls: 'spent',
    };
  }
  if (pace === null) { return { text: '', cls: '' }; }
  const points = Math.round(100 * pace);
  if (points > 10) { return { text: '\u25b2 ' + points + ' ahead', cls: 'ahead' }; }
  if (points < -10) { return { text: '\u25bc ' + (-points) + ' behind', cls: 'behind' }; }
  return { text: '\u25cf on pace', cls: '' };
}

context.handlebars.registerHelper('selectionRows', function (rows, now) {
  const read = routeRead(rows);
  const moment = routeNumber(now);
  const seconds = moment === null ? 0 : moment / 1000;
  return read.routes
    .map((entry) => ({ entry: entry, number: routeNumber(entry.row) }))
    .sort((first, second) => {
      if (first.number === null || second.number === null) { return 0; }
      return first.number - second.number;
    })
    .map((item) => {
      const entry = item.entry;
      const identity = routeIdentity(entry.provider);
      const pace = routePace(entry.left, entry.pace, entry.reset, seconds);
      const percent = entry.left === null ? '' : String(Math.round(100 * entry.left)) + '%';
      return {
        row: entry.row,
        role: entry.role,
        model: entry.model,
        displayName: entry.displayName || entry.model,
        provider: entry.provider,
        providerName: identity.name,
        icon: identity.icon,
        background: identity.background,
        foreground: identity.foreground,
        usedFor: entry.usedFor,
        tag: /^Bulk \d+$/.test(entry.role) ? 'bulk' : '',
        left: pace.text ? (percent ? percent + ' \u00b7 ' + pace.text : pace.text) : percent,
        leftPct: percent,
        leftPace: pace.text,
        leftClass: pace.cls,
      };
    });
});

// The free selection of the page, read out of the rows. The collector
// publishes it; the page never builds a free row out of a candidate or an
// account window.
function freeRead(rows) {
  const selections = new Map();
  for (const row of rows || []) {
    const field = String(row.field || '');
    if (field.indexOf('free_') !== 0) { continue; }
    if (field === 'free_models') { continue; }
    const provider = String(row.provider || '');
    if (!provider) { continue; }
    let entry = selections.get(provider);
    if (!entry) {
      entry = {
        provider: provider,
        model: '',
        displayName: '',
        basis: '',
        left: null,
        pace: null,
        reset: null,
      };
      selections.set(provider, entry);
    }
    const value = routeNumber(row.value);
    if (field === 'free_info') {
      entry.model = row.model || '';
      entry.displayName = row.display_name || row.model || '';
      entry.basis = row.basis || '';
    } else if (field === 'free_left') { entry.left = value; }
    else if (field === 'free_pace') { entry.pace = value; }
    else if (field === 'free_reset') { entry.reset = value; }
  }
  return Array.from(selections.values());
}

// The place of a provider in the capacity cards. A provider the approved
// list does not hold follows the approved ones.
function routeCardOrder(provider) {
  const index = ROUTE_PROVIDERS.findIndex((entry) => entry.account === provider);
  return index < 0 ? ROUTE_PROVIDERS.length : index;
}

// The Left cell of a free row. The basis the collector publishes decides the
// words; a selection with a share reads as a static row does.
function freeLeft(entry, now) {
  if (entry.basis === 'learning') {
    return { pct: '', pace: 'learning window', cls: '' };
  }
  if (entry.basis === 'none') {
    return { pct: '', pace: 'no eligible free model', cls: '' };
  }
  if (entry.left === null) { return { pct: '', pace: 'no reading', cls: '' }; }
  const pace = routePace(entry.left, entry.pace, entry.reset, now);
  return {
    pct: String(Math.round(100 * entry.left)) + '%',
    pace: pace.text,
    cls: pace.cls,
  };
}

// The divider and the free rows, in the order of the capacity cards.
context.handlebars.registerHelper('selectionFreeRows', function (rows, now) {
  const moment = routeNumber(now);
  const seconds = moment === null ? 0 : moment / 1000;
  const entries = freeRead(rows).sort((first, second) => {
    const firstRank = routeCardOrder(first.provider);
    const secondRank = routeCardOrder(second.provider);
    if (firstRank !== secondRank) { return firstRank - secondRank; }
    const left = routeIdentity(first.provider).name;
    const right = routeIdentity(second.provider).name;
    if (left === right) {
      if (first.provider === second.provider) { return 0; }
      return first.provider < second.provider ? -1 : 1;
    }
    return left < right ? -1 : 1;
  });
  if (!entries.length) { return []; }
  const built = [{ group: 'Free' }];
  for (const entry of entries) {
    const identity = routeIdentity(entry.provider);
    const left = freeLeft(entry, seconds);
    const text = left.pct && left.pace
      ? left.pct + ' \u00b7 ' + left.pace
      : (left.pct || left.pace);
    built.push({
      group: '',
      role: 'Free',
      provider: entry.provider,
      providerName: identity.name,
      icon: identity.icon,
      background: identity.background,
      foreground: identity.foreground,
      model: entry.model,
      displayName: entry.displayName || entry.model,
      basis: entry.basis,
      tag: '',
      left: text,
      leftPct: left.pct,
      leftPace: left.pace,
      leftClass: left.cls,
    });
  }
  return built;
});

context.handlebars.registerHelper('selectionRouting', function (rows) {
  const routing = routeRead(rows).routing;
  return routing === null ? 0 : (routing ? 1 : 0);
});

context.handlebars.registerHelper('selectionChip', function (rows) {
  const routing = routeRead(rows).routing;
  return routing ? 'Routing ON \u00b7 static table shown for reference'
    : 'Static table \u00b7 routing OFF';
});

